<div class="project-grid"><?php foreach($cards as $card):?><article class="project-card"><a class="card-visual theme-<?=((int)$card['area_id']%4)?>" href="<?=url('projeto/'.$card['id'])?>" tabindex="-1" aria-hidden="true"><?php if($card['capa']):?><img src="<?=url('arquivo/'.$card['capa'])?>" alt="" loading="lazy" width="600" height="360"><?php else:?><img src="<?=url('assets/project-'.((int)$card['area_id']%4).'.svg')?>" alt="" loading="lazy" width="600" height="360"><?php endif;?><span class="visual-label"><?=e($card['ano'])?></span><?php if($card['destaque']):?><span class="featured-label">Em destaque</span><?php endif;?></a><div class="card-content"><div class="eyebrow"><?=e($card['area'])?></div><h3><a href="<?=url('projeto/'.$card['id'])?>"><?=e($card['titulo'])?></a></h3><p class="card-summary"><?=e(mb_strimwidth($card['resumo'],0,160,'…'))?></p><div class="card-authors"><?=e($card['autores'])?></div><div class="card-bottom"><span><?=e($card['curso'])?></span><a href="<?=url('projeto/'.$card['id'])?>" aria-label="Conhecer <?=e($card['titulo'])?>">↗</a></div></div></article><?php endforeach;?></div>
